UF_FRETE_REDUZIDO = ("SP", "RJ", "MG")


def validar(dados):
    if not dados.get("itens"):
        raise ValueError("pedido sem itens")
    if "@" not in dados.get("email", ""):
        raise ValueError("email inválido")
    for item in dados["itens"]:
        if item["qtd"] <= 0:
            raise ValueError(f"quantidade inválida para {item['sku']}")


def calcular_frete(uf, total):
    if total > 300:
        return 0
    return 15.0 if uf in UF_FRETE_REDUZIDO else 30.0


def calcular_total(itens, tipo_cliente, uf, hoje):
    subtotal = sum(i["preco"] * i["qtd"] for i in itens)
    desconto = calcular_desconto(subtotal, tipo_cliente, hoje)  # R4
    total = round(subtotal - desconto, 2)
    return total + calcular_frete(uf, total)

