class PagFacil:
    def __init__(self, chave):
        self._chave = chave

    def cobrar(self, valor, cartao):
        resp = _post("https://api.pagfacil.com/v1/cobrancas",
                     {"valor_centavos": int(valor * 100), "cartao": cartao},
                     {"Authorization": "Bearer " + self._chave})
        if resp["situacao"] != "APROVADA":
            raise Exception("pagamento recusado: " + resp.get("motivo", ""))
        return resp["id_cobranca"]


