def percentual(taxa):
    return lambda subtotal: subtotal * taxa


def atacado(subtotal):
    return subtotal * (0.15 if subtotal > 1000 else 0.05)


REGRAS_DE_DESCONTO = {
    "vip": percentual(0.10),
    "funcionario": percentual(0.30),
    "atacado": atacado,
}


def calcular_desconto(subtotal, tipo_cliente, hoje):
    regra = REGRAS_DE_DESCONTO.get(tipo_cliente, lambda s: 0)
    desconto = regra(subtotal)
    if hoje.month == 11 and tipo_cliente != "funcionario":  # black friday
        desconto += subtotal * 0.05
    return desconto
